#include "stdafx.h"#include "MnemoWnd.h"#include "PipeClient.h"#include "LogFile.h"void DrawEllipse( HDC hDC, RECT& rc, COLORREF color )  {  HBRUSH hBrush = ::CreateSolidBrush( color );  if ( hBrush )    {    HBRUSH hOldB = (HBRUSH)::SelectObject( hDC, hBrush );    HPEN hPen = ::CreatePen( PS_SOLID,0,color);    if ( hPen )      {      HPEN hOldP = (HPEN)::SelectObject( hDC, hPen );      ::Ellipse( hDC, rc.left, rc.top, rc.right, rc.bottom );      ::SelectObject( hDC, hOldP );      ::DeleteObject( hPen );      }    ::SelectObject( hDC, hOldB );    ::DeleteObject( hBrush );    }  }//void DrawDC( HDC hDC, LPDRAWITEMSTRUCT item )  {	  CLogFile::LogEx (LOGLEVEL_HIGH, "DrawDC_0");	  COLORREF colorButtobBackground=0xCC00FF;	  if (Version==CIPR_SBR)	  {		colorButtobBackground=0xCCCCCC;	  }  HBRUSH hBrush = ::CreateSolidBrush( colorButtobBackground );  DWORD dwThreadID = ::GetCurrentThreadId();  if ( hBrush )    {    ::FillRect( hDC, &item->rcItem, hBrush );    ::DeleteObject( hBrush );    }  ::DrawEdge( hDC, &item->rcItem, EDGE_RAISED, BF_RECT );  //  //  bool isTrue = false;  COLORREF colorBigEllipse = 0xFF0000;  COLORREF clrSmallEllipse=0x111111;  if (Version==CIPR_SBR)	  colorBigEllipse = 0x444444;  //  CPipeClient* pipe = CPipeClient::ms_pMainPipe;  CLogFile::LogEx (LOGLEVEL_LOW, "DrawDC_0: pipe %16lx", pipe);  if ( pipe )  {	  KTcpTransport *pTransport = pipe->GetTcpTransport ();	  UINT_PTR hSocket = pTransport ? pTransport->GetSocket() : 0;	  CLogFile::LogEx (LOGLEVEL_HIGH, "DrawDC_1: connected %d, hSocket %16lx, ms_szServer %s, ms_szCompNm %s",	  pipe->IsConnected(), hSocket, pipe->ms_szServer, pipe->ms_szCompNm);  }  if ( pipe && pipe->IsConnected() )    {    CShSystem& sh = GiveSystem();	CLogFile::LogEx (LOGLEVEL_HIGH, "DrawDC_2: sh.StartStatus %d", (int)sh.StartStatus);    if ( IsTypeOK )	{		switch ( sh.StartStatus )		  {		  case CSystem::STATUS_PAUSE  : colorBigEllipse = 0x33FFFF; break;		  case CSystem::STATUS_START  : colorBigEllipse = 0x00FF00; break;		  default:		  case CSystem::STATUS_UNKNOWN: colorBigEllipse = 0x0000FF; break;		  }		if (Version==CIPR_SBR)		{			switch ( sh.StartStatus )			  {			  case CSystem::STATUS_PAUSE  : colorBigEllipse = 0x959595; break;			  case CSystem::STATUS_START  : colorBigEllipse = 0x959595; break;			  default:			  case CSystem::STATUS_UNKNOWN: colorBigEllipse = 0x959595; clrSmallEllipse=0xe8e8e8; break;			  }		}	}    isTrue = IsTrueModel();    }  //  RECT rc = item->rcItem;  ::InflateRect( &rc, -5, -5 );  ::DrawEllipse( hDC, rc, colorBigEllipse );  //  if ( !isTrue )  {	  if (Version==CIPR_SBR)		  clrSmallEllipse=0xe8e8e8;	  else		  clrSmallEllipse=0x0000FF;  }  if ( clrSmallEllipse!=0x111111 )    {    ::InflateRect( &rc, -4, -4 );    ::DrawEllipse( hDC, rc, clrSmallEllipse );    }  //  }//// Отрисовка состояния моделиvoid DrawBeko( LPDRAWITEMSTRUCT item )  {  static HBITMAP hBitmap = NULL;  static int nWidth  = 0;  static int nHeight = 0;  int h = item->rcItem.bottom-item->rcItem.top;  int w = item->rcItem.right-item->rcItem.left;  if ( nWidth < w || nHeight < h )    {    if ( hBitmap != NULL )      ::DeleteObject( hBitmap );    hBitmap = NULL;    nWidth  = w;    nHeight = h;    }  if ( hBitmap == NULL )    hBitmap = ::CreateCompatibleBitmap( item->hDC, w, h );  if ( hBitmap == NULL )    return;  HDC hdc = ::CreateCompatibleDC( item->hDC );  if ( hdc != NULL )    {    HBITMAP hOld = (HBITMAP)::SelectObject( hdc, hBitmap );    ::DrawDC( hdc, item );    ::BitBlt( item->hDC, item->rcItem.left, item->rcItem.top, w, h, hdc, 0, 0, SRCCOPY );    ::SelectObject( hdc, hOld );    ::DeleteDC( hdc );    }  }//------------------------------------------------------------------------------------------------// Функции, которые используют статическую переменную ms_pMainPipe//// Получение модельного времени__time64_t GiveModelTime()  {	  CLogFile::LogEx (LOGLEVEL_HIGH, "GiveModelTime_1");  CShSystem& sh = GiveSystem();  CLogFile::LogEx (LOGLEVEL_HIGH, "GiveModelTime_2: sh.startTime %d", sh.startTime);  if ( CPipeClient::ms_pMainPipe->IsConnected() && IsTypeOK && sh.startTime )  return sh.TimeM();  CLogFile::LogEx (LOGLEVEL_HIGH, "GiveModelTime_3!!!");  //  return time(NULL);//CTime::GetCurrentTime().GetTime();  }//// Соответствие моделиbool IsTrueModel()  {	  CLogFile::LogEx (LOGLEVEL_HIGH, "IsTrueModel_1");  CShSystem& sh = GiveSystem();  CLogFile::LogEx (LOGLEVEL_HIGH, "IsTrueModel_2");  return CPipeClient::ms_pMainPipe->IsConnected() && IsTypeOK && ( sh.Model == NUMBER_MODEL );  }//// Соответствие работающей моделиbool IsWorkModel()  {  CShSystem& sh = GiveSystem();  return CPipeClient::ms_pMainPipe->IsConnected() && IsTypeOK && ( sh.Model == NUMBER_MODEL ) && (sh.StartStatus == CSystem::STATUS_START );  }//// Отказ РСУbool IsNoPCY()  {  CShSystem& sh = GiveSystem();  if ( !IsTypeOK ) return false;  return IsWorkModel() && sh.bNoPCYWork;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~